async function listBoard(request,env){const hospitalId=clean(new URL(request.url).searchParams.get('hospitalId'),80),global=!hospitalId;const rows=await env.DB.prepare('SELECT b.reference,b.hospital_id,m.hospital_name,b.building,b.floor,m.status,m.created_at,(SELECT COUNT(*) FROM secure_messages a WHERE a.hospital_id=b.hospital_id AND a.title LIKE ? AND a.body LIKE ? || b.reference || ?) AS applications FROM care_board_requests b JOIN secure_messages m ON m.id=b.message_id WHERE (? = ? OR b.hospital_id=?) AND m.status IN (?,?,?) ORDER BY b.start_date,b.start_time LIMIT 500').bind('간병인 신청 · %','%','%','',hospitalId,hospitalId,'접수','검토중','완료').all();const state=s=>s==='완료'?'매칭 완료':s==='검토중'?'매칭 진행':'신청 가능';return json({scope:global?'national':'hospital',items:(rows.results||[]).map(b=>({reference:b.reference,hospitalId:b.hospital_id,hospitalName:b.hospital_name,building:b.building,floor:b.floor,status:state(b.status),applications:Number(b.applications||0)}))},200,{'Access-Control-Allow-Origin':'*'})}
